module adder_pipe_64bit
    (
        input clk,
        input rst_n,
        input i_en,
        input [63:0] adda,
        input [63:0] addb,
        output [64:0] result,
        output reg o_en
    );

    reg [15:0] adda_reg1;
    reg [15:0] adda_reg2;
    reg [15:0] adda_reg3;
    reg [15:0] adda_reg4;

    reg [15:0] addb_reg1;
    reg [15:0] addb_reg2;
    reg [15:0] addb_reg3;
    reg [15:0] addb_reg4;

    reg [15:0] sum1;
    reg [15:0] sum2;
    reg [15:0] sum3;
    reg [15:0] sum4;

    reg i_en_reg1;
    reg i_en_reg2;
    reg i_en_reg3;
    reg i_en_reg4;

    assign adda_reg1 = adda[15:0];
    assign adda_reg2 = adda[31:16];
    assign adda_reg3 = adda[47:32];
    assign adda_reg4 = adda[63:48];

    assign addb_reg1 = addb[15:0];
    assign addb_reg2 = addb[31:16];
    assign addb_reg3 = addb[47:32];
    assign addb_reg4 = addb[63:48];

    assign sum1 = adda_reg1 + addb_reg1;
    assign sum2 = adda_reg2 + addb_reg2 + {16{sum1[15]}};
    assign sum3 = adda_reg3 + addb_reg3 + {16{sum2[15]}};
    assign sum4 = adda_reg4 + addb_reg4 + {16{sum3[15]}};

    assign result = {sum4, sum3, sum2, sum1};

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            i_en_reg1 <= 1'b0;
            i_en_reg2 <= 1'b0;
            i_en_reg3 <= 1'b0;
            i_en_reg4 <= 1'b0;
        end
        else begin
            i_en_reg1 <= i_en;
            i_en_reg2 <= i_en_reg1;
            i_en_reg3 <= i_en_reg2;
            i_en_reg4 <= i_en_reg3;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            o_en <= 1'b0;
        end
        else begin
            o_en <= i_en_reg4;
        end
    end

endmodule

